import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Shield, User, LogOut, Globe, ShieldAlert, FileSearch, Lock, Server, Menu, X } from 'lucide-react';

export default function Navbar({ user, onLogout }) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const navigate = useNavigate();

  // Helper to handle tool clicks: redirects to login with the selected module state
  const handleToolNavigation = (moduleName) => {
    setMobileMenuOpen(false);
    const storedUser = localStorage.getItem('netsentinel_user');
    if (!storedUser) {
      navigate('/login', { 
        state: { 
          from: moduleName, 
          message: 'Authentication Required: Please login before accessing NetSentinel threat tools.' 
        } 
      });
    } else {
      navigate('/dashboard', { state: { defaultModule: moduleName } });
    }
  };

  return (
    <nav className="soc-navbar">
      {/* Top Row: Logo & Mobile Hamburger Button */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
        <Link 
          to="/" 
          style={{ display: 'flex', alignItems: 'center', gap: '8px', textDecoration: 'none' }}
        >
          <Shield size={22} color="var(--accent-cyan)" />
          <span className="hacker-glow" style={{ fontSize: '14px', fontWeight: 'bold', fontFamily: 'var(--font-mono)', color: 'var(--accent-cyan)' }}>
            NET_SENTINEL // SOC
          </span>
        </Link>

        <button 
          className="mobile-menu-btn" 
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          aria-label="Toggle Navigation Menu"
        >
          {mobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
        </button>
      </div>

      {/* Navigation Links: Now redirects directly to Login/Dashboard auth gate */}
      <div className={`nav-links-container ${mobileMenuOpen ? 'mobile-open' : ''}`} style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
        
        <button onClick={() => handleToolNavigation('host_info')} className="cyber-nav-btn" style={{ padding: '6px 10px', fontSize: '11px' }}>
          <Globe size={13} color="var(--accent-cyan)" /> HOST INTEL
        </button>

        <button onClick={() => handleToolNavigation('port_threat')} className="cyber-nav-btn" style={{ padding: '6px 10px', fontSize: '11px' }}>
          <ShieldAlert size={13} color="var(--alert-red)" /> PORT CVE
        </button>

        <button onClick={() => handleToolNavigation('subdomain_dns')} className="cyber-nav-btn" style={{ padding: '6px 10px', fontSize: '11px' }}>
          <FileSearch size={13} color="var(--warning-amber)" /> SUBDOMAINS
        </button>

        <button onClick={() => handleToolNavigation('dir_exposure')} className="cyber-nav-btn" style={{ padding: '6px 10px', fontSize: '11px' }}>
          <Lock size={13} color="var(--accent-green)" /> DIR EXPOSURE
        </button>

        <button onClick={() => handleToolNavigation('ssl_audit')} className="cyber-nav-btn" style={{ padding: '6px 10px', fontSize: '11px' }}>
          <Server size={13} color="var(--accent-cyan)" /> SSL AUDIT
        </button>

        {user ? (
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', width: '100%', justifyContent: 'space-between', marginTop: '4px' }}>
            <span style={{ fontFamily: 'var(--font-mono)', color: 'var(--accent-green)', fontSize: '11px' }}>
              [{user.name}]
            </span>
            <button className="cyber-nav-btn" onClick={() => { onLogout(); navigate('/'); }} style={{ padding: '6px 10px' }}>
              <LogOut size={13} /> LOGOUT
            </button>
          </div>
        ) : (
          <Link to="/login" className="cyber-nav-btn" onClick={() => setMobileMenuOpen(false)} style={{ padding: '6px 12px', fontSize: '11px', backgroundColor: 'rgba(0, 243, 255, 0.15)' }}>
            <User size={13} /> LOGIN
          </Link>
        )}
      </div>
    </nav>
  );
}
